#include <stdio.h>
#include <stdlib.h>

#define MAX_LANGUAGES 100000
#define MAX_PARTICIPANTS 100000

// Union-Find structure
int parent[MAX_PARTICIPANTS + MAX_LANGUAGES + 1];
int rank[MAX_PARTICIPANTS + MAX_LANGUAGES + 1];

void init(int n) {
    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
}

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

void unite(int x, int y) {
    int rx = find(x);
    int ry = find(y);
    if (rx == ry) return;
    if (rank[rx] < rank[ry]) {
        parent[rx] = ry;
    } else if (rank[rx] > rank[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rank[rx]++;
    }
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    // Total nodes: N participants (1..N) and M languages (N+1..N+M)
