    for (int i = 1; i <= N; i++) {
        int k;
        scanf("%d", &k);
        for (int j = 0; j < k; j++) {
            int lang;
            scanf("%d", &lang);
            // Connect participant i with language node (N + lang)
            unite(i, N + lang);
        }
    }

    // Check if all participants are in the same connected component
    int root = find(1);
    for (int i = 2; i <= N; i++) {
        if (find(i) != root) {
            printf("NO\n");
            return 0;
        }
    }

    printf("YES\n");
    return 0;
}

