typedef struct {
    int *parent;
    int *size;
} DSU;

void dsu_init(DSU *d, int n) {
    d->parent = (int *)malloc((n + 1) * sizeof(int));
    d->size = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        d->parent[i] = i;
        d->size[i] = 1;
    }
}

int dsu_find(DSU *d, int x) {
    if (d->parent[x] == x) return x;
    d->parent[x] = dsu_find(d, d->parent[x]);
    return d->parent[x];
}

void dsu_union(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return;
    if (d->size[a] < d->size[b]) {
        int t = a; a = b; b = t;
    }
    d->parent[b] = a;
    d->size[a] += d->size[b];
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    DSU dsu;
    dsu_init(&dsu, N);

    int *firstSpeaker = (int *)calloc(M + 1, sizeof(int));
    int hasAnyLanguage = 0;

    for (int i = 1; i <= N; i++) {
        int k;
        scanf("%d", &k);
        if (k > 0) hasAnyLanguage = 1;
        for (int j = 0; j < k; j++) {
            int lang;
            scanf("%d", &lang);
            if (firstSpeaker[lang] == 0) {
                firstSpeaker[lang] = i;
            } else {
                dsu_union(&dsu, i, firstSpeaker[lang]);
            }
        }
    }

    if (!hasAnyLanguage) {
        printf("NO\n");
        free(dsu.parent);
        free(dsu.size);
        free(firstSpeaker);
        return 0;
    }

    int root = dsu_find(&dsu, 1);
    for (int i = 2; i <= N; i++) {
        if (dsu_find(&dsu, i) != root) {
            printf("NO\n");
            free(dsu.parent);
            free(dsu.size);
            free(firstSpeaker);
            return 0;
        }
    }

    printf("YES\n");

    free(dsu.parent);
    free(dsu.size);
    free(firstSpeaker);
    return 0;
}

